#!/usr/bin/env Rscript

############################################################
## 92_pre_submission_sensitivity_checks_PIPELINE_OBJECTS_FAST.R
##
## Standalone pre-submission sensitivity checks using the same
## objects generated by the modular ROSMAP main-figure pipeline.
##
## FAST version: avoids expensive within-stage permutation loops by
## default, uses vectorized stage residualization, precomputes matched
## samplers, and defaults to 1,000 permutations for first-pass runs.
##
## Run location:
##   Put this file in the same folder as 00_config.R through
##   07_build_matched_null_objects.R, then source/run it from R.
##
## What this checks:
##   CHECK 1. Stage-residualized / within-stage Hsp60/10 client
##            co-movement.
##   CHECK 2. Function-matched Hsp60/10 client vs non-client
##            mitochondrial vulnerability.
##
## GitHub safety:
##   This script does not call git, git add, git commit, or git push.
##   It writes local aggregated outputs only, by default under:
##     file.path(cfg$output_root, "pre_submission_sensitivity_checks")
##   Do not commit these outputs unless you intentionally decide to.
############################################################

suppressPackageStartupMessages({
  library(tidyverse)
  library(broom)
})

sensitivity_seed <- 1300L
set.seed(sensitivity_seed)
options(stringsAsFactors = FALSE)

`%||%` <- function(x, y) {
  if (is.null(x) || length(x) == 0 || all(is.na(x))) y else x
}

############################################################
## 0. Locate scripts and source config/helpers
############################################################

this_file <- tryCatch(
  normalizePath(sys.frame(1)$ofile, mustWork = TRUE),
  error = function(e) NA_character_
)

if (is.na(this_file) && requireNamespace("rstudioapi", quietly = TRUE)) {
  this_file <- tryCatch(
    normalizePath(rstudioapi::getActiveDocumentContext()$path, mustWork = TRUE),
    error = function(e) NA_character_
  )
}

## Resolve the R pipeline directory deterministically.
##
## When R/92 is sourced from a validator, sys.frame(1)$ofile can refer to
## the caller rather than this script. Therefore do not use `ofile` to choose
## the working directory. Prefer the repository root/current R directory,
## then fall back to cfg$project_dir if cfg is already loaded.

wd_now <- normalizePath(getwd(), mustWork = TRUE)

if (
  file.exists(file.path(wd_now, "R", "00_config.R")) &&
  file.exists(file.path(wd_now, "R", "01_utils.R"))
) {
  script_dir <- normalizePath(file.path(wd_now, "R"), mustWork = TRUE)
} else if (
  file.exists(file.path(wd_now, "00_config.R")) &&
  file.exists(file.path(wd_now, "01_utils.R"))
) {
  script_dir <- wd_now
} else if (
  exists("cfg", envir = .GlobalEnv, inherits = FALSE) &&
  !is.null(cfg$project_dir) &&
  file.exists(file.path(cfg$project_dir, "R", "00_config.R")) &&
  file.exists(file.path(cfg$project_dir, "R", "01_utils.R"))
) {
  script_dir <- normalizePath(
    file.path(cfg$project_dir, "R"),
    mustWork = TRUE
  )
} else {
  stop(
    "Could not locate the R pipeline directory. ",
    "Run this from the repository root or from the R/ directory.",
    call. = FALSE
  )
}

old_wd <- getwd()
setwd(script_dir)
on.exit(setwd(old_wd), add = TRUE)

message("Script directory: ", getwd())

for (script in c("00_config.R", "01_utils.R")) {
  script_path <- file.path(script_dir, script)

  if (!file.exists(script_path)) {
    stop(
      "Missing required pipeline script: ",
      script_path,
      call. = FALSE
    )
  }

  source(script_path, local = .GlobalEnv)
}

sens_bool <- function(name, default = "TRUE") {
  tolower(Sys.getenv(name, default)) %in% c("true", "t", "1", "yes", "y")
}

sens_int <- function(name, default) {
  out <- suppressWarnings(as.integer(Sys.getenv(name, as.character(default))))
  if (!is.finite(out) || is.na(out) || out < 0) default else out
}

sens_cfg <- list(
  output_dir = Sys.getenv(
    "SENSITIVITY_OUTPUT_DIR",
    file.path(cfg$output_root, "pre_submission_sensitivity_checks")
  ),
  ## Fast default for interactive testing. For final archival runs, set
  ## SENSITIVITY_N_PERM=10000 or set check-specific values below.
  n_perm = sens_int("SENSITIVITY_N_PERM", 1000),
  n_perm_check1 = sens_int("SENSITIVITY_N_PERM_CHECK1", sens_int("SENSITIVITY_N_PERM", 1000)),
  n_perm_check2 = sens_int("SENSITIVITY_N_PERM_CHECK2", sens_int("SENSITIVITY_N_PERM", 1000)),
  top_n_late_decline = sens_int("SENSITIVITY_TOP_N_LATE_DECLINE", 40),
  min_selected_genes = sens_int("SENSITIVITY_MIN_SELECTED_GENES", 8),
  min_clients_per_module = sens_int("SENSITIVITY_MIN_CLIENTS_PER_MODULE", 3),
  min_nonclients_per_module = sens_int("SENSITIVITY_MIN_NONCLIENTS_PER_MODULE", 3),
  corr_method = Sys.getenv("SENSITIVITY_CORR_METHOD", "spearman"),
  run_check1 = sens_bool("SENSITIVITY_RUN_CHECK1", "TRUE"),
  run_check2 = sens_bool("SENSITIVITY_RUN_CHECK2", "TRUE"),
  ## This is the main speed lever. Observed within-stage correlations are
  ## still written, but permutation nulls within each stage are skipped by default.
  run_within_stage_nulls = sens_bool("SENSITIVITY_WITHIN_STAGE_NULLS", "FALSE"),
  write_full_null_distributions = sens_bool("SENSITIVITY_WRITE_FULL_NULL_DISTRIBUTIONS", "FALSE"),
  save_plots = sens_bool("SENSITIVITY_SAVE_PLOTS", "TRUE"),
  progress_every = sens_int("SENSITIVITY_PROGRESS_EVERY", 100),
  source_upstream_if_missing = sens_bool("SENSITIVITY_SOURCE_UPSTREAM_IF_MISSING", "TRUE")
)

dir.create(sens_cfg$output_dir, recursive = TRUE, showWarnings = FALSE)
message("Sensitivity output directory: ", sens_cfg$output_dir)
message("Check 1 permutations: ", sens_cfg$n_perm_check1)
message("Check 2 permutations: ", sens_cfg$n_perm_check2)
message("Within-stage permutation nulls: ", sens_cfg$run_within_stage_nulls)

############################################################
## 1. Load required pipeline objects, sourcing upstream only if needed
############################################################

obj_path <- function(name) file.path(cfg$object_dir, paste0(name, ".rds"))
table_path <- function(name) file.path(cfg$table_dir, paste0(name, ".csv"))

load_obj_if_needed <- function(name, assign_as = name, required = TRUE) {
  if (exists(assign_as, envir = .GlobalEnv, inherits = FALSE)) {
    return(get(assign_as, envir = .GlobalEnv, inherits = FALSE))
  }
  path <- obj_path(name)
  if (file.exists(path)) {
    x <- readRDS(path)
    assign(assign_as, x, envir = .GlobalEnv)
    message("Loaded object from RDS: ", assign_as, " <- ", path)
    return(x)
  }
  if (isTRUE(required)) {
    stop("Missing required object/RDS: ", name, " at ", path, call. = FALSE)
  }
  NULL
}

try_load_existing_outputs <- function() {
  invisible(lapply(c(
    "prot_mat_adj", "prot_meta_adj", "protein_covars",
    "all_hsp60_10_client_tbl", "priority_tbl", "pathway_gene_sets",
    "all_hsp60_10_clients"
  ), function(nm) load_obj_if_needed(nm, required = FALSE)))

  if (exists("prot_mat_adj", envir = .GlobalEnv, inherits = FALSE) &&
      !exists("prot_mat", envir = .GlobalEnv, inherits = FALSE)) {
    assign("prot_mat", get("prot_mat_adj", envir = .GlobalEnv), envir = .GlobalEnv)
  }

  null_input_csv <- table_path("figure5_null_input_COVARIATE_ADJUSTED")
  if (!exists("null_input_tbl", envir = .GlobalEnv, inherits = FALSE) && file.exists(null_input_csv)) {
    assign("null_input_tbl", readr::read_csv(null_input_csv, show_col_types = FALSE), envir = .GlobalEnv)
    message("Loaded null_input_tbl from CSV: ", null_input_csv)
  }
}

required_for_checks <- c(
  "prot_mat", "prot_meta_adj", "all_hsp60_10_client_tbl",
  "priority_tbl", "pathway_gene_sets", "null_input_tbl"
)

try_load_existing_outputs()
missing_now <- required_for_checks[!vapply(required_for_checks, exists, logical(1), envir = .GlobalEnv)]

if (length(missing_now) > 0 && isTRUE(sens_cfg$source_upstream_if_missing)) {
  message("Missing upstream object(s): ", paste(missing_now, collapse = ", "))
  message("Sourcing 02-07 to rebuild required objects...")
  for (script in c(
    "02_load_data.R",
    "03_build_adjusted_core_objects.R",
    "04_build_pathway_sets_all_clients.R",
    "05_build_adjusted_all_client_tables.R",
    "06_build_cognition_objects.R",
    "07_build_matched_null_objects.R"
  )) {
    if (!file.exists(script)) stop("Missing required upstream script: ", script, call. = FALSE)
    source(script, local = .GlobalEnv)
  }
}

missing_final <- required_for_checks[!vapply(required_for_checks, exists, logical(1), envir = .GlobalEnv)]
if (length(missing_final) > 0) {
  stop(
    "Still missing required object(s): ", paste(missing_final, collapse = ", "),
    "\nRun the modular pipeline through 07_build_matched_null_objects.R first, ",
    "or leave SENSITIVITY_SOURCE_UPSTREAM_IF_MISSING=TRUE.",
    call. = FALSE
  )
}

############################################################
## 2. Shared helpers
############################################################

safe_num2 <- function(x) suppressWarnings(as.numeric(x))

safe_mean <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  mean(x)
}

safe_median <- function(x) {
  x <- x[is.finite(x)]
  if (length(x) == 0) return(NA_real_)
  median(x)
}

empirical_p_greater <- function(null_values, observed) {
  null_values <- null_values[is.finite(null_values)]
  if (length(null_values) == 0 || !is.finite(observed)) return(NA_real_)
  (1 + sum(null_values >= observed)) / (length(null_values) + 1)
}

safe_wilcox_greater <- function(x, y) {
  x <- x[is.finite(x)]
  y <- y[is.finite(y)]
  if (length(x) < 2 || length(y) < 2) return(NA_real_)
  out <- tryCatch(
    suppressWarnings(stats::wilcox.test(x, y, alternative = "greater", exact = FALSE)$p.value),
    error = function(e) NA_real_
  )
  out
}

normalize_stage <- function(x) {
  x <- as.character(x)
  dplyr::case_when(
    x %in% c("NCI", "MCI", "AD") ~ x,
    TRUE ~ NA_character_
  )
}

pairwise_cor_summary <- function(cor_mat, genes, label = NA_character_) {
  genes <- intersect(unique(genes), rownames(cor_mat))
  genes <- intersect(genes, colnames(cor_mat))

  if (length(genes) < 3) {
    return(tibble(
      set_label = label,
      n_genes = length(genes),
      n_pairs = 0L,
      mean_r = NA_real_,
      median_r = NA_real_,
      mean_abs_r = NA_real_,
      median_abs_r = NA_real_,
      mean_fisher_z = NA_real_
    ))
  }

  vals <- cor_mat[genes, genes, drop = FALSE]
  vals <- vals[upper.tri(vals)]
  vals <- vals[is.finite(vals)]
  vals_clip <- pmin(pmax(vals, -0.999999), 0.999999)

  tibble(
    set_label = label,
    n_genes = length(genes),
    n_pairs = length(vals),
    mean_r = safe_mean(vals),
    median_r = safe_median(vals),
    mean_abs_r = safe_mean(abs(vals)),
    median_abs_r = safe_median(abs(vals)),
    mean_fisher_z = safe_mean(atanh(vals_clip))
  )
}

progress_msg <- function(i, n, label) {
  if (n <= 0) return(invisible(NULL))
  if (i == 1 || i == n || (sens_cfg$progress_every > 0 && i %% sens_cfg$progress_every == 0)) {
    message(label, ": ", i, "/", n, " iterations")
  }
  invisible(NULL)
}

make_strata_key <- function(df, cols) {
  if (length(cols) == 0) return(rep("ALL", nrow(df)))
  vals <- lapply(cols, function(cc) {
    v <- as.character(df[[cc]])
    v[is.na(v)] <- "MISSING"
    v
  })
  do.call(paste, c(vals, sep = "\r"))
}

unique_col_sets <- function(x) {
  keep <- !duplicated(vapply(x, function(z) paste(z, collapse = "\r"), character(1)))
  x[keep]
}

select_viable_match_cols <- function(selected_tbl, pool_tbl, try_cols_list, replace = FALSE) {
  try_cols_list <- unique_col_sets(try_cols_list)

  for (cols in try_cols_list) {
    if (length(cols) > 0 && (!all(cols %in% names(selected_tbl)) || !all(cols %in% names(pool_tbl)))) next

    selected_keys <- make_strata_key(selected_tbl, cols)
    pool_keys <- make_strata_key(pool_tbl, cols)
    selected_counts <- table(selected_keys)
    pool_counts <- table(pool_keys)

    if (length(selected_counts) == 0 || length(pool_counts) == 0) next
    if (!all(names(selected_counts) %in% names(pool_counts))) next

    available <- as.integer(pool_counts[names(selected_counts)])
    needed <- as.integer(selected_counts)

    ok <- if (isTRUE(replace)) all(available > 0) else all(available >= needed)
    if (isTRUE(ok)) return(cols)
  }

  NULL
}

build_fast_gene_sampler <- function(selected_tbl, pool_tbl, try_cols_list) {
  selected_tbl <- selected_tbl |> dplyr::filter(!is.na(gene), gene != "") |> dplyr::distinct(gene, .keep_all = TRUE)
  pool_tbl <- pool_tbl |> dplyr::filter(!is.na(gene), gene != "") |> dplyr::distinct(gene, .keep_all = TRUE)

  cols <- select_viable_match_cols(selected_tbl, pool_tbl, try_cols_list, replace = FALSE)
  if (is.null(cols)) {
    stop("Could not build a matched gene sampler without replacement. Try lowering selected-set size or matching constraints.", call. = FALSE)
  }

  selected_keys <- make_strata_key(selected_tbl, cols)
  pool_keys <- make_strata_key(pool_tbl, cols)
  needed <- table(selected_keys)
  pool_genes <- split(pool_tbl$gene, pool_keys)

  force(needed)
  force(pool_genes)
  force(cols)

  list(
    matched_on = if (length(cols) == 0) "none" else paste(cols, collapse = ";"),
    sampler = function() {
      unlist(lapply(names(needed), function(k) {
        sample(pool_genes[[k]], size = as.integer(needed[[k]]), replace = FALSE)
      }), use.names = FALSE)
    }
  )
}

build_fast_row_sampler <- function(selected_tbl, pool_tbl, try_cols_list) {
  selected_tbl <- selected_tbl |> dplyr::filter(!is.na(gene), gene != "")
  pool_tbl <- pool_tbl |> dplyr::filter(!is.na(gene), gene != "")

  cols <- select_viable_match_cols(selected_tbl, pool_tbl, try_cols_list, replace = TRUE)
  if (is.null(cols)) {
    stop("Could not build a matched row sampler. Try lowering matching constraints.", call. = FALSE)
  }

  selected_keys <- make_strata_key(selected_tbl, cols)
  pool_keys <- make_strata_key(pool_tbl, cols)
  needed <- table(selected_keys)
  pool_rows <- split(seq_len(nrow(pool_tbl)), pool_keys)

  force(needed)
  force(pool_rows)
  force(cols)
  force(pool_tbl)

  list(
    matched_on = if (length(cols) == 0) "none" else paste(cols, collapse = ";"),
    sampler = function() {
      idx <- unlist(lapply(names(needed), function(k) {
        candidates <- pool_rows[[k]]
        sample(candidates, size = as.integer(needed[[k]]), replace = length(candidates) < as.integer(needed[[k]]))
      }), use.names = FALSE)
      pool_tbl[idx, , drop = FALSE]
    }
  )
}

write_null_outputs <- function(null_tbl, full_file, summary_file) {
  if (isTRUE(sens_cfg$write_full_null_distributions)) {
    readr::write_csv(null_tbl, full_file)
  }

  null_summary <- null_tbl |>
    dplyr::group_by(dplyr::across(dplyr::any_of(c("context", "selection", "group", "metric")))) |>
    dplyr::summarise(
      n_iter = dplyr::n(),
      mean_abs_r_mean = if ("mean_abs_r" %in% names(dplyr::pick(dplyr::everything()))) mean(mean_abs_r, na.rm = TRUE) else NA_real_,
      mean_abs_r_q025 = if ("mean_abs_r" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(mean_abs_r, 0.025, na.rm = TRUE) else NA_real_,
      mean_abs_r_q500 = if ("mean_abs_r" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(mean_abs_r, 0.500, na.rm = TRUE) else NA_real_,
      mean_abs_r_q975 = if ("mean_abs_r" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(mean_abs_r, 0.975, na.rm = TRUE) else NA_real_,
      null_mean_value = if ("null_value" %in% names(dplyr::pick(dplyr::everything()))) mean(null_value, na.rm = TRUE) else NA_real_,
      null_q025 = if ("null_value" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(null_value, 0.025, na.rm = TRUE) else NA_real_,
      null_q500 = if ("null_value" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(null_value, 0.500, na.rm = TRUE) else NA_real_,
      null_q975 = if ("null_value" %in% names(dplyr::pick(dplyr::everything()))) stats::quantile(null_value, 0.975, na.rm = TRUE) else NA_real_,
      .groups = "drop"
    )
  readr::write_csv(null_summary, summary_file)
  invisible(null_summary)
}

sample_matched_genes <- function(selected_tbl, pool_tbl, match_cols) {
  selected_tbl <- selected_tbl |> dplyr::filter(!is.na(gene), gene != "")
  pool_tbl <- pool_tbl |> dplyr::filter(!is.na(gene), gene != "") |> dplyr::distinct(gene, .keep_all = TRUE)
  n_needed <- nrow(selected_tbl)

  try_cols_list <- list(
    match_cols,
    intersect(match_cols, c("functional_class", "abundance_bin")),
    intersect(match_cols, "functional_class"),
    intersect(match_cols, "abundance_bin"),
    character()
  )
  try_cols_list <- unique(try_cols_list)

  for (cols in try_cols_list) {
    if (length(cols) == 0) {
      if (nrow(pool_tbl) >= n_needed) return(sample(pool_tbl$gene, n_needed, replace = FALSE))
      next
    }

    if (!all(cols %in% names(selected_tbl)) || !all(cols %in% names(pool_tbl))) next

    selected_counts <- selected_tbl |>
      dplyr::mutate(dplyr::across(dplyr::all_of(cols), ~replace_na(as.character(.x), "MISSING"))) |>
      dplyr::count(dplyr::across(dplyr::all_of(cols)), name = "n_needed")

    pool_counts <- pool_tbl |>
      dplyr::mutate(dplyr::across(dplyr::all_of(cols), ~replace_na(as.character(.x), "MISSING"))) |>
      dplyr::count(dplyr::across(dplyr::all_of(cols)), name = "n_available")

    ok <- selected_counts |>
      dplyr::left_join(pool_counts, by = cols) |>
      dplyr::mutate(n_available = replace_na(n_available, 0L)) |>
      dplyr::summarise(ok = all(n_available >= n_needed), .groups = "drop") |>
      dplyr::pull(ok)

    if (!isTRUE(ok)) next

    sampled <- selected_counts |>
      dplyr::group_split(dplyr::across(dplyr::all_of(cols))) |>
      purrr::map(function(stratum_row) {
        cond <- rep(TRUE, nrow(pool_tbl))
        for (cc in cols) {
          selected_val <- replace_na(as.character(stratum_row[[cc]][1]), "MISSING")
          pool_val <- replace_na(as.character(pool_tbl[[cc]]), "MISSING")
          cond <- cond & pool_val == selected_val
        }
        sample(pool_tbl$gene[cond], stratum_row$n_needed[1], replace = FALSE)
      }) |>
      unlist(use.names = FALSE)

    return(sampled)
  }

  stop("Could not sample a matched gene set without replacement. Try lowering selected-set size.", call. = FALSE)
}

sample_matched_rows_with_replacement <- function(selected_tbl, pool_tbl, match_cols) {
  selected_tbl <- selected_tbl |> dplyr::filter(!is.na(gene), gene != "")
  pool_tbl <- pool_tbl |> dplyr::filter(!is.na(gene), gene != "")

  try_cols_list <- list(
    match_cols,
    intersect(match_cols, c("functional_module", "abundance_bin")),
    intersect(match_cols, "functional_module"),
    intersect(match_cols, "abundance_bin"),
    character()
  )
  try_cols_list <- unique(try_cols_list)

  for (cols in try_cols_list) {
    if (length(cols) == 0) {
      if (nrow(pool_tbl) == 0) next
      return(pool_tbl[sample(seq_len(nrow(pool_tbl)), nrow(selected_tbl), replace = nrow(pool_tbl) < nrow(selected_tbl)), , drop = FALSE])
    }

    if (!all(cols %in% names(selected_tbl)) || !all(cols %in% names(pool_tbl))) next

    selected_counts <- selected_tbl |>
      dplyr::mutate(dplyr::across(dplyr::all_of(cols), ~replace_na(as.character(.x), "MISSING"))) |>
      dplyr::count(dplyr::across(dplyr::all_of(cols)), name = "n_needed")

    pool_counts <- pool_tbl |>
      dplyr::mutate(dplyr::across(dplyr::all_of(cols), ~replace_na(as.character(.x), "MISSING"))) |>
      dplyr::count(dplyr::across(dplyr::all_of(cols)), name = "n_available")

    possible <- selected_counts |>
      dplyr::left_join(pool_counts, by = cols) |>
      dplyr::mutate(n_available = replace_na(n_available, 0L)) |>
      dplyr::summarise(ok = all(n_available > 0), .groups = "drop") |>
      dplyr::pull(ok)

    if (!isTRUE(possible)) next

    sampled <- selected_counts |>
      dplyr::group_split(dplyr::across(dplyr::all_of(cols))) |>
      purrr::map_dfr(function(stratum_row) {
        cond <- rep(TRUE, nrow(pool_tbl))
        for (cc in cols) {
          selected_val <- replace_na(as.character(stratum_row[[cc]][1]), "MISSING")
          pool_val <- replace_na(as.character(pool_tbl[[cc]]), "MISSING")
          cond <- cond & pool_val == selected_val
        }
        candidates <- pool_tbl[cond, , drop = FALSE]
        candidates[sample(seq_len(nrow(candidates)), stratum_row$n_needed[1], replace = nrow(candidates) < stratum_row$n_needed[1]), , drop = FALSE]
      })

    return(sampled)
  }

  stop("Could not sample matched non-client rows.", call. = FALSE)
}

