        matching_abundance = safe_num2(matching_abundance),
        abundance_bin = as.character(abundance_bin)
      ) |>
      dplyr::distinct(gene, .keep_all = TRUE),
    by = "gene"
  ) |>
  dplyr::mutate(
    abundance_bin = dplyr::if_else(
      is.na(abundance_bin) & is.finite(matching_abundance),
      paste0("bin_", dplyr::ntile(matching_abundance, 10)),
      abundance_bin
    )
  )

readr::write_csv(client_metrics, file.path(sens_cfg$output_dir, "check_inputs_detected_client_metrics.csv"))

message("Detected Hsp60/10 client proteins available for sensitivity checks: ", nrow(client_metrics))

