## 4. CHECK 1: Stage-residualized / within-stage co-movement
############################################################

make_protein_stage_meta <- function() {
  if (!"clinical_stage" %in% colnames(prot_meta_adj)) {
    stop(
      "prot_meta_adj is missing canonical clinical_stage. ",
      "Run the corrected production pipeline before R/92.",
      call. = FALSE
    )
  }

  out <- prot_meta_adj |>
    dplyr::transmute(
      SampleID = as.character(.data$SampleID),
      stage = normalize_stage(.data$clinical_stage),
      stage = factor(stage, levels = c("NCI", "MCI", "AD"))
    ) |>
    dplyr::filter(
      !is.na(.data$SampleID),
      !is.na(.data$stage),
      .data$SampleID %in% colnames(prot_mat)
    ) |>
    dplyr::distinct(.data$SampleID, .keep_all = TRUE)

  stage_counts <- out |>
    dplyr::count(.data$stage, name = "n_samples") |>
    tidyr::complete(
      stage = factor(c("NCI", "MCI", "AD"), levels = c("NCI", "MCI", "AD")),
      fill = list(n_samples = 0L)
    )

  expected_counts <- c(NCI = 168L, MCI = 97L, AD = 109L)
  observed_counts <- stats::setNames(
    stage_counts$n_samples,
    as.character(stage_counts$stage)
  )

  if (!identical(
    as.integer(observed_counts[names(expected_counts)]),
    as.integer(expected_counts)
  )) {
    stop(
      "Unexpected primary-stage protein sample counts in R/92. Observed: ",
      paste(
        names(observed_counts),
        observed_counts,
        sep = "=",
        collapse = ", "
      ),
      "; expected NCI=168, MCI=97, AD=109.",
      call. = FALSE
    )
  }

  readr::write_csv(
    stage_counts,
    file.path(
      sens_cfg$output_dir,
      "check1_primary_clinical_stage_sample_counts.csv"
    )
  )

  out
}

residualize_matrix_on_stage <- function(mat, stage_meta) {
  ## y ~ stage residuals are equivalent to subtracting the within-stage
  ## gene mean. This vectorized implementation is much faster than fitting
  ## one lm() per protein.
  sample_ids <- intersect(colnames(mat), stage_meta$SampleID)
  stage_meta <- stage_meta[match(sample_ids, stage_meta$SampleID), , drop = FALSE]
  mat <- mat[, sample_ids, drop = FALSE]
  mat <- as.matrix(mat)
  mode(mat) <- "numeric"

  out <- matrix(NA_real_, nrow = nrow(mat), ncol = ncol(mat), dimnames = dimnames(mat))
  for (stg in levels(stage_meta$stage)) {
    idx <- which(stage_meta$stage == stg)
    if (length(idx) < 2) next
    mu <- rowMeans(mat[, idx, drop = FALSE], na.rm = TRUE)
    out[, idx] <- sweep(mat[, idx, drop = FALSE], 1, mu, FUN = "-")
  }

  out[rowSums(is.finite(out)) < 10, ] <- NA_real_
  out
}

make_cor_mat <- function(mat, method = sens_cfg$corr_method) {
  suppressWarnings(stats::cor(t(mat), use = "pairwise.complete.obs", method = method))
}

select_check1_sets <- function(client_metrics) {
  cm <- client_metrics |>
    dplyr::filter(is.finite(protein_late_decline_magnitude), gene %in% rownames(prot_mat)) |>
    dplyr::arrange(dplyr::desc(protein_late_decline_magnitude))

  n_top <- min(sens_cfg$top_n_late_decline, nrow(cm))
  top_late_decline <- cm |>
    dplyr::slice_head(n = n_top) |>
    dplyr::mutate(selection = "top_late_decline_clients")

  high_both <- cm |>
    dplyr::filter(late_decline_percentile >= 75, centrality_percentile >= 75)

  if (nrow(high_both) >= sens_cfg$min_selected_genes) {
    late_decline_central <- high_both |>
      dplyr::arrange(dplyr::desc(late_decline_percentile + centrality_percentile)) |>
      dplyr::mutate(selection = "late_decline_top_quartile_and_centrality_top_quartile")
  } else {
    late_decline_central <- cm |>
      dplyr::filter(is.finite(centrality_percentile)) |>
      dplyr::mutate(rank_sum = late_decline_percentile + centrality_percentile) |>
      dplyr::arrange(dplyr::desc(rank_sum)) |>
      dplyr::slice_head(n = n_top) |>
      dplyr::mutate(selection = "top_combined_late_decline_and_centrality_rank")
  }

  list(
    top_late_decline_clients = top_late_decline,
    late_decline_central_clients = late_decline_central
  )
}

run_comovement_null <- function(cor_mat, selected_tbl, pool_tbl, label, context) {
  selected_tbl <- selected_tbl |> dplyr::filter(gene %in% rownames(cor_mat), gene %in% colnames(cor_mat))
  pool_tbl <- pool_tbl |>
    dplyr::filter(gene %in% rownames(cor_mat), gene %in% colnames(cor_mat), !gene %in% selected_tbl$gene)

  if (nrow(selected_tbl) < sens_cfg$min_selected_genes) {
    return(list(
      summary = tibble(
        context = context,
        selection = label,
        n_genes = nrow(selected_tbl),
        error = "Too few selected genes after matrix overlap"
      ),
      null = tibble()
    ))
  }

  match_cols <- c("functional_class", "abundance_bin")
  match_cols <- match_cols[vapply(match_cols, function(cc) cc %in% names(client_metrics) && any(!is.na(client_metrics[[cc]])), logical(1))]
  try_cols_list <- list(
    match_cols,
    intersect(match_cols, c("functional_class", "abundance_bin")),
    intersect(match_cols, "functional_class"),
    intersect(match_cols, "abundance_bin"),
    character()
  )

  obs <- pairwise_cor_summary(cor_mat, selected_tbl$gene, label = label)
  sampler_info <- build_fast_gene_sampler(selected_tbl, pool_tbl, try_cols_list)

  n_iter <- sens_cfg$n_perm_check1
  null_stats <- vector("list", n_iter)
  for (i in seq_len(n_iter)) {
    progress_msg(i, n_iter, paste0("CHECK 1 ", context, " / ", label))
    sampled <- sampler_info$sampler()
    null_stats[[i]] <- pairwise_cor_summary(cor_mat, sampled, label = label) |>
      dplyr::mutate(iter = i)
  }
  null <- dplyr::bind_rows(null_stats)

  summary <- obs |>
    dplyr::mutate(
      context = context,
      selection = label,
      null_mean_abs_r = mean(null$mean_abs_r, na.rm = TRUE),
      null_sd_abs_r = stats::sd(null$mean_abs_r, na.rm = TRUE),
      delta_mean_abs_r = mean_abs_r - null_mean_abs_r,
      empirical_p_abs_r_greater = empirical_p_greater(null$mean_abs_r, mean_abs_r),
      null_mean_r = mean(null$mean_r, na.rm = TRUE),
      null_sd_r = stats::sd(null$mean_r, na.rm = TRUE),
      delta_mean_r = mean_r - null_mean_r,
      empirical_p_mean_r_greater = empirical_p_greater(null$mean_r, mean_r),
      n_perm = n_iter,
      corr_method = sens_cfg$corr_method,
      matched_on = sampler_info$matched_on,
      error = NA_character_
    )

  list(summary = summary, null = null)
}

run_check1 <- function() {
  message("\nCHECK 1: stage-residualized / within-stage co-movement")

  stage_meta <- make_protein_stage_meta()
  genes <- intersect(client_metrics$gene, rownames(prot_mat))
  mat_client <- prot_mat[genes, stage_meta$SampleID, drop = FALSE]

  resid_mat <- residualize_matrix_on_stage(mat_client, stage_meta)
  cor_resid <- make_cor_mat(resid_mat)

  selected_sets <- select_check1_sets(client_metrics)
  pool_tbl <- client_metrics |> dplyr::filter(gene %in% genes)

  selected_audit <- purrr::imap_dfr(selected_sets, function(tbl, nm) {
    tbl |> dplyr::mutate(selection_name = nm, .before = 1)
  })
  readr::write_csv(selected_audit, file.path(sens_cfg$output_dir, "check1_selected_client_sets.csv"))

  residual_results <- purrr::imap(selected_sets, function(tbl, nm) {
    run_comovement_null(cor_resid, tbl, pool_tbl, nm, context = "stage_residualized_all_samples")
  })

  residual_summary <- purrr::map_dfr(residual_results, "summary")
  residual_null <- purrr::imap_dfr(residual_results, function(x, nm) {
    x$null |> dplyr::mutate(selection = nm, context = "stage_residualized_all_samples")
  })

  readr::write_csv(residual_summary, file.path(sens_cfg$output_dir, "check1_stage_residualized_comovement_summary.csv"))
  write_null_outputs(
    residual_null,
    full_file = file.path(sens_cfg$output_dir, "check1_stage_residualized_null_distributions.csv"),
    summary_file = file.path(sens_cfg$output_dir, "check1_stage_residualized_null_distribution_summary.csv")
  )

  within_stage_summary <- purrr::map_dfr(levels(stage_meta$stage), function(stg) {
    sample_ids <- stage_meta |> dplyr::filter(stage == stg) |> dplyr::pull(SampleID)
    if (length(sample_ids) < 20) return(tibble())
    cor_stage <- make_cor_mat(mat_client[, sample_ids, drop = FALSE])

    if (isTRUE(sens_cfg$run_within_stage_nulls)) {
      purrr::imap_dfr(selected_sets, function(tbl, nm) {
        run_comovement_null(cor_stage, tbl, pool_tbl, nm, context = paste0("within_stage_", gsub(" ", "_", stg)))$summary |>
          dplyr::mutate(stage = as.character(stg), n_samples = length(sample_ids), nulls_run = TRUE)
      })
    } else {
      purrr::imap_dfr(selected_sets, function(tbl, nm) {
        pairwise_cor_summary(cor_stage, tbl$gene, label = nm) |>
          dplyr::mutate(
            context = paste0("within_stage_", gsub(" ", "_", stg)),
            selection = nm,
            stage = as.character(stg),
            n_samples = length(sample_ids),
            nulls_run = FALSE,
            note = "Observed within-stage co-movement only; set SENSITIVITY_WITHIN_STAGE_NULLS=TRUE for permutation nulls."
          )
      })
    }
  })
  readr::write_csv(within_stage_summary, file.path(sens_cfg$output_dir, "check1_within_stage_comovement_summary.csv"))

  client_cor <- cor_resid[genes, genes, drop = FALSE]
  residual_degree <- purrr::map_dfr(genes, function(g) {
    vals <- client_cor[g, setdiff(genes, g)]
    vals <- vals[is.finite(vals)]
    tibble::tibble(
      gene = g,
      residual_mean_abs_r_to_other_clients = safe_mean(abs(vals)),
      residual_median_abs_r_to_other_clients = safe_median(abs(vals)),
      residual_mean_r_to_other_clients = safe_mean(vals),
      residual_positive_fraction = safe_mean(vals > 0)
    )
  }) |>
    dplyr::left_join(client_metrics, by = "gene")

  residual_centrality_tests <- tibble::tibble(
    predictor = c("protein_late_decline_magnitude", "late_decline_percentile", "hub_mean_abs_cor", "centrality_percentile"),
    outcome = "residual_mean_abs_r_to_other_clients"
  ) |>
    dplyr::mutate(
      n = purrr::map_int(predictor, function(pred) {
        sum(is.finite(residual_degree[[pred]]) & is.finite(residual_degree$residual_mean_abs_r_to_other_clients))
      }),
      spearman_rho = purrr::map_dbl(predictor, function(pred) {
        ok <- is.finite(residual_degree[[pred]]) & is.finite(residual_degree$residual_mean_abs_r_to_other_clients)
        if (sum(ok) < 10) return(NA_real_)
        unname(suppressWarnings(stats::cor(residual_degree[[pred]][ok], residual_degree$residual_mean_abs_r_to_other_clients[ok], method = "spearman")))
      }),
      p_value = purrr::map_dbl(predictor, function(pred) {
        ok <- is.finite(residual_degree[[pred]]) & is.finite(residual_degree$residual_mean_abs_r_to_other_clients)
        if (sum(ok) < 10) return(NA_real_)
        suppressWarnings(stats::cor.test(residual_degree[[pred]][ok], residual_degree$residual_mean_abs_r_to_other_clients[ok], method = "spearman", exact = FALSE)$p.value)
      })
    )

  readr::write_csv(residual_degree, file.path(sens_cfg$output_dir, "check1_residual_comovement_degree_by_client.csv"))
  readr::write_csv(residual_centrality_tests, file.path(sens_cfg$output_dir, "check1_residual_comovement_association_tests.csv"))

  if (isTRUE(sens_cfg$save_plots) && nrow(residual_null) > 0) {
    p_null <- residual_null |>
      dplyr::filter(is.finite(mean_abs_r)) |>
      ggplot2::ggplot(ggplot2::aes(x = mean_abs_r)) +
      ggplot2::geom_histogram(bins = 60) +
      ggplot2::facet_wrap(~selection, scales = "free_y") +
      ggplot2::geom_vline(
        data = residual_summary,
        ggplot2::aes(xintercept = mean_abs_r),
        linewidth = 0.7
      ) +
      ggplot2::labs(
        title = "Stage-residualized Hsp60/10 client co-movement nulls",
        x = "Mean absolute residual pairwise correlation",
        y = "Permutation count"
      ) +
      ggplot2::theme_classic(base_size = 10)

    ggplot2::ggsave(
      file.path(sens_cfg$output_dir, "check1_stage_residualized_comovement_nulls.pdf"),
      p_null,
      width = 7.0,
      height = 4.5,
      units = "in"
    )
  }

  if (isTRUE(sens_cfg$save_plots)) {
    p_resid <- residual_degree |>
      dplyr::filter(is.finite(protein_late_decline_magnitude), is.finite(residual_mean_abs_r_to_other_clients)) |>
      ggplot2::ggplot(ggplot2::aes(x = protein_late_decline_magnitude, y = residual_mean_abs_r_to_other_clients)) +
      ggplot2::geom_point(alpha = 0.75) +
      ggplot2::geom_smooth(method = "lm", se = TRUE, linewidth = 0.7) +
      ggplot2::labs(
        title = "Late-stage decline versus stage-residualized co-movement",
        x = "Protein late-stage decline magnitude",
        y = "Mean absolute residual correlation to other clients"
      ) +
      ggplot2::theme_classic(base_size = 10)

    ggplot2::ggsave(
      file.path(sens_cfg$output_dir, "check1_late_decline_vs_stage_residualized_comovement.pdf"),
      p_resid,
      width = 5.5,
      height = 4.0,
      units = "in"
    )
  }

  list(
    residual_summary = residual_summary,
    within_stage_summary = within_stage_summary,
    residual_degree = residual_degree,
    residual_centrality_tests = residual_centrality_tests
  )
}

############################################################
## 5. CHECK 2: Function-matched client vs non-client mitochondrial proteins
############################################################

module_from_client_class <- function(x) {
  dplyr::case_when(
    stringr::str_detect(x, regex("translation", ignore_case = TRUE)) ~ "Mitochondrial translation",
    stringr::str_detect(x, regex("pyruvate|TCA", ignore_case = TRUE)) ~ "Pyruvate / TCA metabolism",
    stringr::str_detect(x, regex("OXPHOS|ETC|ATP synthase", ignore_case = TRUE)) ~ "OXPHOS / ETC / ATP synthase",
    stringr::str_detect(x, regex("FAO|lipid|fatty", ignore_case = TRUE)) ~ "FAO / lipid metabolism",
    stringr::str_detect(x, regex("proteostasis|quality|chaperone|protease", ignore_case = TRUE)) ~ "Mitochondrial proteostasis / quality control",
    TRUE ~ NA_character_
  )
}

build_function_module_table <- function() {
  client_modules <- all_hsp60_10_client_tbl |>
    dplyr::transmute(
      gene = as.character(gene),
      functional_module = module_from_client_class(as.character(functional_class)),
      module_source = "client_functional_class"
    ) |>
    dplyr::filter(!is.na(functional_module), functional_module != "") |>
    dplyr::distinct(gene, functional_module, .keep_all = TRUE)

  pathway_map <- c(
    Mito_translation_non_Hsp60_10 = "Mitochondrial translation",
    OXPHOS_ETC_non_Hsp60_10 = "OXPHOS / ETC / ATP synthase",
    TCA_pyruvate_metabolism_non_Hsp60_10 = "Pyruvate / TCA metabolism",
    FAO_metabolism_non_Hsp60_10 = "FAO / lipid metabolism",
    Mito_protein_quality_control_non_Hsp60_10 = "Mitochondrial proteostasis / quality control"
  )

  bg_modules <- purrr::imap_dfr(pathway_gene_sets, function(genes, nm) {
    if (!nm %in% names(pathway_map)) return(tibble())
    tibble::tibble(
      gene = as.character(genes),
      functional_module = unname(pathway_map[[nm]]),
      module_source = nm
    )
  }) |>
    dplyr::distinct(gene, functional_module, .keep_all = TRUE)

  dplyr::bind_rows(client_modules, bg_modules) |>
    dplyr::distinct(gene, functional_module, .keep_all = TRUE)
}

run_metric_matched_null <- function(df, metric_col, group_label) {
  df <- df |>
    dplyr::filter(is.finite(.data[[metric_col]]), !is.na(is_client), !is.na(functional_module))

  clients <- df |> dplyr::filter(is_client)
  nonclients <- df |> dplyr::filter(!is_client)

  if (nrow(clients) < sens_cfg$min_clients_per_module ||
      nrow(nonclients) < sens_cfg$min_nonclients_per_module) {
    return(tibble(
      group = group_label,
      metric = metric_col,
      n_clients = nrow(clients),
      n_nonclients = nrow(nonclients),
      observed_client_mean = NA_real_,
      null_nonclient_mean = NA_real_,
      delta_client_vs_matched_nonclient = NA_real_,
      empirical_p_greater = NA_real_,
      n_perm = sens_cfg$n_perm_check2
    ))
  }

  match_cols <- c("functional_module", "abundance_bin")
  match_cols <- match_cols[vapply(match_cols, function(cc) cc %in% names(df) && any(!is.na(df[[cc]])), logical(1))]
  try_cols_list <- list(
    match_cols,
    intersect(match_cols, c("functional_module", "abundance_bin")),
    intersect(match_cols, "functional_module"),
    intersect(match_cols, "abundance_bin"),
    character()
  )

  observed <- mean(clients[[metric_col]], na.rm = TRUE)
  sampler_info <- build_fast_row_sampler(clients, nonclients, try_cols_list)

  n_iter <- sens_cfg$n_perm_check2
  null_means <- numeric(n_iter)
  for (i in seq_len(n_iter)) {
    progress_msg(i, n_iter, paste0("CHECK 2 ", group_label, " / ", metric_col))
    sampled <- sampler_info$sampler()
    null_means[[i]] <- mean(sampled[[metric_col]], na.rm = TRUE)
  }

  tibble(
    group = group_label,
    metric = metric_col,
    n_clients = nrow(clients),
    n_nonclients = nrow(nonclients),
    observed_client_mean = observed,
    null_nonclient_mean = mean(null_means, na.rm = TRUE),
    null_nonclient_sd = stats::sd(null_means, na.rm = TRUE),
    delta_client_vs_matched_nonclient = observed - null_nonclient_mean,
    empirical_p_greater = empirical_p_greater(null_means, observed),
    n_perm = n_iter,
    matched_on = sampler_info$matched_on
  )
}

run_check2 <- function() {
  message("\nCHECK 2: function-matched client vs non-client mitochondrial proteins")

  module_tbl <- build_function_module_table()

  metrics_for_function <- null_input_tbl |>
    dplyr::transmute(
      gene = as.character(gene),
      is_client = as.logical(is_hsp60_10_client),
      protein_late_decline_magnitude = safe_num2(protein_late_decline_magnitude),
      inverse_braak_magnitude = safe_num2(inverse_braak_magnitude),
      pathology_vulnerability_score = safe_num2(pathology_vulnerability_score),
      matching_abundance = safe_num2(matching_abundance),
      abundance_bin = as.character(abundance_bin)
    ) |>
    dplyr::mutate(
      abundance_bin = dplyr::if_else(
        is.na(abundance_bin) & is.finite(matching_abundance),
        paste0("bin_", dplyr::ntile(matching_abundance, 10)),
        abundance_bin
      )
    ) |>
    dplyr::left_join(module_tbl, by = "gene") |>
    dplyr::filter(!is.na(functional_module), functional_module != "")

  module_counts <- metrics_for_function |>
    dplyr::group_by(functional_module) |>
    dplyr::summarise(
      n_client_rows = sum(is_client, na.rm = TRUE),
      n_nonclient_rows = sum(!is_client, na.rm = TRUE),
      n_unique_client_genes = dplyr::n_distinct(gene[is_client]),
      n_unique_nonclient_genes = dplyr::n_distinct(gene[!is_client]),
      .groups = "drop"
    ) |>
    dplyr::arrange(dplyr::desc(n_unique_client_genes + n_unique_nonclient_genes))

  eligible_modules <- module_counts |>
    dplyr::filter(
      n_unique_client_genes >= sens_cfg$min_clients_per_module,
      n_unique_nonclient_genes >= sens_cfg$min_nonclients_per_module
    ) |>
    dplyr::pull(functional_module)

  eligible <- metrics_for_function |>
    dplyr::filter(functional_module %in% eligible_modules)

  metric_cols <- c("protein_late_decline_magnitude", "inverse_braak_magnitude", "pathology_vulnerability_score")

  direct_tests <- purrr::map_dfr(metric_cols, function(metric_col) {
    eligible |>
      dplyr::group_by(functional_module) |>
      dplyr::summarise(
        metric = metric_col,
        n_clients = sum(is_client & is.finite(.data[[metric_col]]), na.rm = TRUE),
        n_nonclients = sum(!is_client & is.finite(.data[[metric_col]]), na.rm = TRUE),
        client_median = safe_median(.data[[metric_col]][is_client]),
        nonclient_median = safe_median(.data[[metric_col]][!is_client]),
        delta_median_client_minus_nonclient = client_median - nonclient_median,
        wilcox_p_greater = safe_wilcox_greater(.data[[metric_col]][is_client], .data[[metric_col]][!is_client]),
        .groups = "drop"
      ) |>
      dplyr::filter(n_clients >= sens_cfg$min_clients_per_module, n_nonclients >= sens_cfg$min_nonclients_per_module)
  }) |>
    dplyr::group_by(metric) |>
    dplyr::mutate(wilcox_fdr = p.adjust(wilcox_p_greater, method = "BH")) |>
    dplyr::ungroup()

  module_matched <- purrr::map_dfr(metric_cols, function(metric_col) {
    purrr::map_dfr(eligible_modules, function(mod) {
      run_metric_matched_null(
        eligible |> dplyr::filter(functional_module == mod),
        metric_col = metric_col,
        group_label = mod
      )
    })
  }) |>
    dplyr::group_by(metric) |>
    dplyr::mutate(empirical_fdr = p.adjust(empirical_p_greater, method = "BH")) |>
    dplyr::ungroup()

  overall_matched <- purrr::map_dfr(metric_cols, function(metric_col) {
    run_metric_matched_null(
      eligible,
      metric_col = metric_col,
      group_label = "overall_function_and_abundance_matched"
    )
  })

  regression_tests <- purrr::map_dfr(metric_cols, function(metric_col) {
    df_fit <- eligible |>
      dplyr::mutate(metric_value = .data[[metric_col]]) |>
      dplyr::distinct(gene, is_client, functional_module, matching_abundance, metric_value, .keep_all = TRUE) |>
      dplyr::filter(is.finite(metric_value), !is.na(functional_module)) |>
      dplyr::mutate(
        client_status = factor(if_else(is_client, "client", "nonclient"), levels = c("nonclient", "client")),
        matching_abundance_z = as.numeric(scale(matching_abundance))
      )

    form <- if (sum(is.finite(df_fit$matching_abundance_z)) >= 20) {
      stats::as.formula("metric_value ~ client_status + functional_module + matching_abundance_z")
    } else {
      stats::as.formula("metric_value ~ client_status + functional_module")
    }

    fit <- tryCatch(stats::lm(form, data = df_fit), error = function(e) NULL)
    if (is.null(fit)) {
      return(tibble(metric = metric_col, term = NA_character_, estimate = NA_real_, p_value = NA_real_, n = nrow(df_fit), formula = deparse(form)))
    }

    broom::tidy(fit) |>
      dplyr::filter(term == "client_statusclient") |>
      dplyr::transmute(metric = metric_col, term, estimate, std_error = std.error, statistic, p_value = p.value, n = nrow(df_fit), formula = deparse(form))
  })

  readr::write_csv(module_tbl, file.path(sens_cfg$output_dir, "check2_gene_to_function_module_map.csv"))
  readr::write_csv(module_counts, file.path(sens_cfg$output_dir, "check2_function_module_counts.csv"))
  readr::write_csv(direct_tests, file.path(sens_cfg$output_dir, "check2_direct_within_module_tests.csv"))
  readr::write_csv(module_matched, file.path(sens_cfg$output_dir, "check2_module_abundance_matched_permutation_tests.csv"))
  readr::write_csv(overall_matched, file.path(sens_cfg$output_dir, "check2_overall_function_abundance_matched_tests.csv"))
  readr::write_csv(regression_tests, file.path(sens_cfg$output_dir, "check2_function_adjusted_regression_tests.csv"))

  if (isTRUE(sens_cfg$save_plots)) {
    p_module <- direct_tests |>
      dplyr::filter(metric == "protein_late_decline_magnitude") |>
      dplyr::mutate(functional_module = forcats::fct_reorder(functional_module, delta_median_client_minus_nonclient)) |>
      ggplot2::ggplot(ggplot2::aes(x = delta_median_client_minus_nonclient, y = functional_module)) +
      ggplot2::geom_vline(xintercept = 0, linewidth = 0.4) +
      ggplot2::geom_point(size = 2) +
      ggplot2::labs(
        title = "Client decline within matched mitochondrial functional modules",
        x = "Median late-stage decline magnitude: client minus non-client",
        y = NULL
      ) +
      ggplot2::theme_classic(base_size = 10)

    ggplot2::ggsave(
      file.path(sens_cfg$output_dir, "check2_function_matched_late_decline_effects.pdf"),
      p_module,
      width = 6.5,
      height = max(3.5, 0.35 * max(1, length(eligible_modules))),
      units = "in"
    )
  }

  list(
    module_counts = module_counts,
    direct_tests = direct_tests,
    module_matched = module_matched,
    overall_matched = overall_matched,
    regression_tests = regression_tests
  )
}

